<h1>Dashboard</h1>
<div class="stats"><div class="stat"><span>Total sales</span><b><?= money((float)$sales) ?></b></div><div class="stat"><span>Orders</span><b><?= (int)$orders ?></b></div><div class="stat"><span>Customers</span><b><?= (int)$customers ?></b></div><div class="stat"><span>Products</span><b><?= (int)$products ?></b></div></div>
<div class="agrid"><div class="card"><h3>Low stock</h3><?php foreach ($low as $p): ?><div class="srow"><span><?= e($p['name']) ?></span><b><?= (int)$p['stock_quantity'] ?> left</b></div><?php endforeach; ?></div>
<div class="card"><h3>Pending orders</h3><?php foreach ($pend as $o): ?><div class="srow"><a href="/admin/orders/<?= (int)$o['id'] ?>"><?= e($o['order_number']) ?></a><b><?= money((float)$o['total']) ?></b></div><?php endforeach; ?></div></div>
<div class="card"><h3>Recent orders</h3><div class="tbl"><table><tr><th>Number</th><th>Total</th><th>Status</th><th>Date</th></tr><?php foreach ($recent as $o): ?><tr><td><a href="/admin/orders/<?= (int)$o['id'] ?>"><?= e($o['order_number']) ?></a></td><td><?= money((float)$o['total']) ?></td><td><?= e($o['status']) ?></td><td><?= e($o['created_at']) ?></td></tr><?php endforeach; ?></table></div></div>
<div class="card"><h3>Last 7 days sales</h3><canvas id="salesChart" height="180" data-chart='<?= json_encode($daily, JSON_HEX_TAG | JSON_HEX_APOS | JSON_HEX_QUOT | JSON_HEX_AMP) ?>'></canvas><p class="mono"><?php foreach ($daily as $d) echo e($d['d']) . ' → RM ' . number_format((float)$d['t'], 2) . ' · '; ?></p></div>
